+                                        join r in UnitWork.Find<Relevance>(null) on me.Id equals r.SecondId
+                                        join role in UnitWork.Find<Role>(null) on r.FirstId equals role.Id
+                                        join mo in modules on new { roleId = role.Id, MId = me.ModuleId } equals new { roleId = mo.roleId, MId = mo.m.Id }
+                                        where r.Key == Define.ROLEELEMENT && roles.Contains(r.FirstId)
