+        private static bool HasRegisterSalaryPermission(bool isViewAll, List<string> orgIds, bool isViewSelf, RegistrationStatusEnums? CurrentStatus
+            , string OrganizationIds, string loginUserId, HumanResourceApprovalResp resp)
+        {
+            // 拥有查询全部数据的权限
+            if (isViewAll)
+            {
+                return true;
+            }
+
+            // 审批过程中，创建人和审批人可以查看
+            if (CurrentStatus != RegistrationStatusEnums.Ended && (resp.CreateUserId == loginUserId || resp.CurrentApproverId?.Contains(loginUserId) == true))
+            {
+                return true;
+            }
+
+            // 部门范围权限
+            if (orgIds.Contains(OrganizationIds))
+            {
+                return true;
+            }
+
+            // 查看自己
+            if (CurrentStatus == RegistrationStatusEnums.Ended && loginUserId == resp.UserId && isViewSelf)
+            {
+                return true;
+            }
+
+            return false;
+        }
