+            // 部门范围权限
+            if (orgIds.Contains(OrganizationIds))
+            {
+                return true;
+            }
+
+            // 查看自己
+            if (CurrentStatus == RegistrationStatusEnums.Ended && loginUserId == resp.UserId && isViewSelf)
+            {
+                return true;
+            }
+
+            return false;
+        }
