+
+        /// <summary>
+        /// 解密
+        /// </summary>
+        /// <param name="cipherText"></param>
+        /// <returns></returns>
+        private string Decrypt(string cipherText)
+        {
+            if (string.IsNullOrEmpty(_key))
+            {
+                return cipherText;
+            }
+            var key = Convert.FromBase64String(_key);
+            using (Aes aes = Aes.Create())
+            {
+                if (string.IsNullOrEmpty(cipherText))
+                {
+                    return string.Empty;
+                }
+                var cipherBytes = Convert.FromBase64String(cipherText);
+                aes.Key = key;
+                var iv = new byte[aes.BlockSize / 8]; // 提取IV
+                Array.Copy(cipherBytes, 0, iv, 0, iv.Length);
+                aes.IV = iv;
+
+                ICryptoTransform decryptor = aes.CreateDecryptor();
+                using (MemoryStream ms = new MemoryStream(cipherBytes, iv.Length, cipherBytes.Length - iv.Length))
+                {
+                    using (CryptoStream cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read))
+                    {
+                        using (StreamReader sr = new StreamReader(cs))
+                        {
+                            return sr.ReadToEnd();
+                        }
+                    }
+                }
+            }
+        }
+
+        private decimal DecryptToDecimal(string cipherText)
+        {
+            return decimal.TryParse(Decrypt(cipherText), out var temp) ? temp : 0;
+        }
+    }
